import math

def parse_amount(text):
    if text is None:
        raise ValueError("Empty or None input")

    # Strip whitespace
    text = text.strip()

    # Reject empty strings
    if not text:
        raise ValueError("Empty input")

    # Normalize: replace comma with dot for decimal separator
    normalized = text.replace(',', '.')

    # Try to parse as float
    try:
        value = float(normalized)
    except ValueError:
        raise ValueError(f"Cannot parse '{text}' as a number")

    # Reject negative values
    if value < 0:
        raise ValueError("Negative values not allowed")

    # Reject non-finite values (inf, nan)
    if math.isfinite(value) is False:
        raise ValueError(f"Non-finite value detected: {value}")

    return value

